#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1e9+7;
const ll BASE1 = 911382323;
const ll BASE2 = 972663749;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, R, C;
    cin >> H >> W >> R >> C;

    vector<string> region(H);
    for (int i = 0; i < H; i++) {
        cin >> region[i];
    }

    vector<string> pattern(R);
    for (int i = 0; i < R; i++) {
        cin >> pattern[i];
    }

    // Precompute powers
    vector<ll> pow1(W+1, 1), pow2(H+1, 1);
    for (int i = 1; i <= W; i++) pow1[i] = pow1[i-1] * BASE1 % MOD;
    for (int i = 1; i <= H; i++) pow2[i] = pow2[i-1] * BASE2 % MOD;

    // Hash each row of region
    vector<vector<ll>> rowHash(H, vector<ll>(W+1, 0));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            rowHash[i][j+1] = (rowHash[i][j] * BASE1 + region[i][j]) % MOD;
        }
    }

    // Hash each row of pattern
    vector<ll> patRowHash(R, 0);
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            patRowHash[i] = (patRowHash[i] * BASE1 + pattern[i][j]) % MOD;
        }
    }

    // Compute 2D hash of pattern
    ll patHash = 0;
    for (int i = 0; i < R; i++) {
        patHash = (patHash * BASE2 + patRowHash[i]) % MOD;
    }

    // Slide over region
    for (int i = 0; i + R <= H; i++) {
        // Get row hashes for columns 0..C-1
        vector<ll> curRowHash(R);
        for (int r = 0; r < R; r++) {
            curRowHash[r] = (rowHash[i+r][C] - rowHash[i+r][0] * pow1[C] % MOD + MOD) % MOD;
        }
        ll curHash = 0;
        for (int r = 0; r < R; r++) {
            curHash = (curHash * BASE2 + curRowHash[r]) % MOD;
        }
        if (curHash == patHash) {
            cout << i << " " << 0 << "\n";
        }

        // Slide horizontally
        for (int j = 1; j + C <= W; j++) {
            for (int r = 0; r < R; r++) {
                curRowHash[r] = ( (rowHash[i+r][j+C] - rowHash[i+r][j] * pow1[C] % MOD + MOD) % MOD );
            }
            curHash = 0;
            for (int r = 0; r < R; r++) {
                curHash = (curHash * BASE2 + curRowHash[r]) % MOD;
            }
            if (curHash == patHash) {
                cout << i << " " << j << "\n";
            }
        }
    }

    return 0;
}

