#define MAXH 2000
#define MAXW 2000
#define MOD 97266353ULL
#define BASE 91138233ULL

unsigned long long powB[MAXW+1], powR[MAXH+1];
unsigned long long rowHashG[MAXH][MAXW];
unsigned long long rowHashP[MAXH][MAXW];
unsigned long long gridHash[MAXH][MAXW];
unsigned long long patHash;
char grid[MAXH][MAXW+1];
char pat[MAXH][MAXW+1];

int main() {
    int H, W, R, C;
    scanf("%d %d %d %d", &H, &W, &R, &C);
    for (int i = 0; i < H; i++) scanf("%s", grid[i]);
    for (int i = 0; i < R; i++) scanf("%s", pat[i]);

    // precompute powers
    powB[0] = 1;
    for (int i = 1; i <= W; i++) powB[i] = (powB[i-1] * BASE) % MOD;
    powR[0] = 1;
    for (int i = 1; i <= H; i++) powR[i] = (powR[i-1] * BASE) % MOD;

    // row hashing for grid
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < C; j++) {
            rowHashG[i][0] = (rowHashG[i][0] * BASE + grid[i][j]) % MOD;
        }
        for (int j = 1; j + C <= W; j++) {
            rowHashG[i][j] = ((rowHashG[i][j-1] - grid[i][j-1] * powB[C-1] % MOD + MOD) % MOD * BASE + grid[i][j+C-1]) % MOD;
        }
    }

    // row hashing for pattern
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            rowHashP[i][0] = (rowHashP[i][0] * BASE + pat[i][j]) % MOD;
        }
    }

    // column hash for pattern (single value)
    patHash = 0;
    for (int i = 0; i < R; i++) {
        patHash = (patHash * BASE + rowHashP[i][0]) % MOD;
    }

    // column hash for grid (each starting column)
    for (int j = 0; j + C <= W; j++) {
        for (int i = 0; i < R; i++) {
            gridHash[0][j] = (gridHash[0][j] * BASE + rowHashG[i][j]) % MOD;
        }
        for (int i = 1; i + R <= H; i++) {
            gridHash[i][j] = ((gridHash[i-1][j] - rowHashG[i-1][j] * powR[R-1] % MOD + MOD) % MOD * BASE + rowHashG[i+R-1][j]) % MOD;
        }
    }

    // compare
    for (int i = 0; i + R <= H; i++) {
        for (int j = 0; j + C <= W; j++) {
            if (gridHash[i][j] == patHash) {
                printf("%d %d\n", i, j);
            }
        }
    }

    return 0;
}

