#define MAXN 1010
#define BASE1 1000003ULL
#define BASE2 1000033ULL

char text[MAXN][MAXN];
char pat[MAXN][MAXN];

uint64_t rowHashText[MAXN][MAXN];
uint64_t rowHashPat[MAXN];

uint64_t colPow[MAXN], rowPow[MAXN];

int main(void) {
    int H, W, R, C;
    if (scanf("%d %d", &H, &W) != 2) return 0;
    for (int i = 0; i < H; i++) scanf("%s", text[i]);
    scanf("%d %d", &R, &C);
    for (int i = 0; i < R; i++) scanf("%s", pat[i]);

    if (R > H || C > W) return 0;

    rowPow[0] = 1;
    for (int i = 1; i <= C; i++) rowPow[i] = rowPow[i - 1] * BASE1;

    colPow[0] = 1;
    for (int i = 1; i <= R; i++) colPow[i] = colPow[i - 1] * BASE2;

    for (int i = 0; i < H; i++) {
        uint64_t pref[MAXN];
        pref[0] = 0;
        for (int j = 0; j < W; j++) {
            pref[j + 1] = pref[j] * BASE1 + (unsigned char)text[i][j];
        }
        for (int j = 0; j + C <= W; j++) {
            rowHashText[i][j] = pref[j + C] - pref[j] * rowPow[C];
        }
    }

    for (int i = 0; i < R; i++) {
        uint64_t h = 0;
        for (int j = 0; j < C; j++) {
            h = h * BASE1 + (unsigned char)pat[i][j];
        }
        rowHashPat[i] = h;
    }

    uint64_t patternHash = 0;
    for (int i = 0; i < R; i++) {
        patternHash = patternHash * BASE2 + rowHashPat[i];
    }

    for (int j = 0; j + C <= W; j++) {
        uint64_t pref[MAXN];
        pref[0] = 0;
        for (int i = 0; i < H; i++) {
            pref[i + 1] = pref[i] * BASE2 + rowHashText[i][j];
        }
        for (int i = 0; i + R <= H; i++) {
            uint64_t h = pref[i + R] - pref[i] * colPow[R];
            if (h == patternHash) {
                printf("%d %d\n", i, j);
            }
        }
    }

    return 0;
}

