import java.io.*;
import java.util.*;

public class Main {
    static final long MOD1 = 1_000_000_007L;
    static final long MOD2 = 1_000_000_009L;
    static final long BASE_ROW1 = 911382323L;
    static final long BASE_ROW2 = 972663749L;
    static final long BASE_COL1 = 911382323L - 12345;
    static final long BASE_COL2 = 972663749L - 54321;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();

        char[][] text = new char[H][];
        for (int i = 0; i < H; i++) text[i] = fs.next().toCharArray();

        int R = fs.nextInt();
        int C = fs.nextInt();

        char[][] pat = new char[R][];
        for (int i = 0; i < R; i++) pat[i] = fs.next().toCharArray();

        // Pattern 2D hash
        long[] powC1 = buildPowers(C, BASE_ROW1, MOD1);
        long[] powC2 = buildPowers(C, BASE_ROW2, MOD2);
        long[] powR1 = buildPowers(R, BASE_COL1, MOD1);
        long[] powR2 = buildPowers(R, BASE_COL2, MOD2);

        long[] patRowHash1 = new long[R];
        long[] patRowHash2 = new long[R];
        for (int i = 0; i < R; i++) {
            long h1 = 0, h2 = 0;
            for (int j = 0; j < C; j++) {
                int v = pat[i][j];
                h1 = (h1 * BASE_ROW1 + v) % MOD1;
                h2 = (h2 * BASE_ROW2 + v) % MOD2;
            }
            patRowHash1[i] = h1;
            patRowHash2[i] = h2;
        }

        long patternHash1 = 0, patternHash2 = 0;
        for (int i = 0; i < R; i++) {
            patternHash1 = (patternHash1 * BASE_COL1 + patRowHash1[i]) % MOD1;
            patternHash2 = (patternHash2 * BASE_COL2 + patRowHash2[i]) % MOD2;
        }

        // Row-wise rolling hashes for every row in text, window width C
        int outW = W - C + 1;
        int outH = H - R + 1;
        long[][] rowWin1 = new long[H][Math.max(0, outW)];
        long[][] rowWin2 = new long[H][Math.max(0, outW)];

        for (int i = 0; i < H; i++) {
            if (outW <= 0) continue;
            long[] pref1 = new long[W + 1];
            long[] pref2 = new long[W + 1];
            for (int j = 0; j < W; j++) {
                pref1[j + 1] = (pref1[j] * BASE_ROW1 + text[i][j]) % MOD1;
                pref2[j + 1] = (pref2[j] * BASE_ROW2 + text[i][j]) % MOD2;
            }
            for (int j = 0; j < outW; j++) {
                rowWin1[i][j] = subHash(pref1, j, j + C, powC1[C], MOD1);
                rowWin2[i][j] = subHash(pref2, j, j + C, powC2[C], MOD2);
            }
        }

        StringBuilder sb = new StringBuilder();

        // For each column start, do vertical rolling hash on row-window hashes
        for (int col = 0; col < outW; col++) {
            long[] pref1 = new long[H + 1];
            long[] pref2 = new long[H + 1];
            for (int i = 0; i < H; i++) {
                pref1[i + 1] = (pref1[i] * BASE_COL1 + rowWin1[i][col]) % MOD1;
                pref2[i + 1] = (pref2[i] * BASE_COL2 + rowWin2[i][col]) % MOD2;
            }
            for (int row = 0; row < outH; row++) {
                long h1 = subHash(pref1, row, row + R, powR1[R], MOD1);
                long h2 = subHash(pref2, row, row + R, powR2[R], MOD2);
                if (h1 == patternHash1 && h2 == patternHash2) {
                    sb.append(row).append(' ').append(col).append('\n');
                }
            }
        }

        System.out.print(sb.toString());
    }

    static long[] buildPowers(int n, long base, long mod) {
        long[] p = new long[n + 1];
        p[0] = 1;
        for (int i = 1; i <= n; i++) p[i] = (p[i - 1] * base) % mod;
        return p;
    }

    static long subHash(long[] pref, int l, int r, long powLen, long mod) {
        long res = (pref[r] - (pref[l] * powLen) % mod) % mod;
        if (res < 0) res += mod;
        return res;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

